const int PIN_LED = 8;
const int PIN_BOTON = 2;

void setup() {
  pinMode(PIN_LED, OUTPUT);
  pinMode(PIN_BOTON, INPUT_PULLUP);
}

void loop() {
  if (digitalRead(PIN_BOTON) == LOW) {
    digitalWrite(PIN_LED, HIGH);
  } else {
    digitalWrite(PIN_LED, LOW);
  }
}

const int PIN_POTE = A0;
const int PIN_LED = 9;

void setup() {
  pinMode(PIN_LED, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  int adc = analogRead(PIN_POTE);
  int pwm = map(adc, 0, 1023, 0, 255);
  analogWrite(PIN_LED, pwm);
  Serial.print("ADC=");
  Serial.print(adc);
  Serial.print(" PWM=");
  Serial.println(pwm);
  delay(40);
}

const int PIN_TRIG = 7;
const int PIN_ECHO = 6;
const int PIN_LED = 8;

float medirCm() {
  digitalWrite(PIN_TRIG, LOW);
  delayMicroseconds(2);
  digitalWrite(PIN_TRIG, HIGH);
  delayMicroseconds(10);
  digitalWrite(PIN_TRIG, LOW);
  long duracion = pulseIn(PIN_ECHO, HIGH, 30000);
  if (duracion == 0) return -1;
  return duracion * 0.0343 / 2.0;
}

void setup() {
  pinMode(PIN_TRIG, OUTPUT);
  pinMode(PIN_ECHO, INPUT);
  pinMode(PIN_LED, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  float cm = medirCm();
  Serial.println(cm);
  digitalWrite(PIN_LED, (cm > 0 && cm < 15) ? HIGH : LOW);
  delay(120);
}

#include <Servo.h>

Servo miServo;

void setup() {
  miServo.attach(9);
}

void loop() {
  for (int ang = 0; ang <= 180; ang++) {
    miServo.write(ang);
    delay(12);
  }
  for (int ang = 180; ang >= 0; ang--) {
    miServo.write(ang);
    delay(12);
  }
}

#include <Servo.h>

const int PIN_TRIG = 7;
const int PIN_ECHO = 6;
const int PIN_LED = 8;
const float UMBRAL_CM = 18.0;

Servo servoAlerta;

float medirCm() {
  digitalWrite(PIN_TRIG, LOW);
  delayMicroseconds(2);
  digitalWrite(PIN_TRIG, HIGH);
  delayMicroseconds(10);
  digitalWrite(PIN_TRIG, LOW);
  long d = pulseIn(PIN_ECHO, HIGH, 30000);
  if (d == 0) return -1;
  return d * 0.0343 / 2.0;
}

void setup() {
  pinMode(PIN_TRIG, OUTPUT);
  pinMode(PIN_ECHO, INPUT);
  pinMode(PIN_LED, OUTPUT);
  servoAlerta.attach(9);
  servoAlerta.write(0);
  Serial.begin(9600);
}

void loop() {
  float cm = medirCm();
  Serial.println(cm);
  bool cerca = (cm > 0 && cm < UMBRAL_CM);
  digitalWrite(PIN_LED, cerca ? HIGH : LOW);
  servoAlerta.write(cerca ? 90 : 0);
  delay(100);
}
